# Sentinal external shell hook for bash (COMMANDS capture).
# Generated by `sentinal hook bash`. It reports Command text, cwd, timing, and
# exit status to the private sentinald socket in the background. It never reads
# terminal output or keystrokes and never prints anything.
#
# Command start uses a DEBUG trap armed once per prompt. If another tool already
# owns the DEBUG trap, the hook uses bash-preexec's arrays when available and
# otherwise stays inactive rather than replacing that trap.
if [[ $- == *i* && -z "${SENTINAL_SESSION_ID-}" && "${SENTINAL_DISABLE-}" != 1 && -z "${__sentinal_hook_loaded-}" ]]; then
  __sentinal_hook_loaded=1
  __sentinal_seq=0
  __sentinal_active=
  __sentinal_ready=
  __sentinal_status=0
  __sentinal_text=
  __sentinal_histnum=
  __sentinal_pc_array=

  __sentinal_report() {
    [[ -n "${SENTINAL_SESSION_ID-}" || "${SENTINAL_DISABLE-}" == 1 ]] && return 0
    ( SENTINAL_HOOK_TEXT="$__sentinal_text" @SENTINAL_BIN@ hook report "$@" --pid "$$" --shell bash --at "${EPOCHREALTIME-}" </dev/null >/dev/null 2>&1 & )
  }

  # Start a Command whose full text is $1.
  __sentinal_start() {
    __sentinal_seq=$((__sentinal_seq + 1))
    __sentinal_active=1
    __sentinal_text=$1
    __sentinal_report start --seq "$__sentinal_seq"
  }

  __sentinal_precmd() {
    __sentinal_status=$?
    # Keep __sentinal_arm last even if a tool appended to PROMPT_COMMAND later.
    if [[ -n $__sentinal_pc_array ]]; then
      if [[ ${PROMPT_COMMAND[${#PROMPT_COMMAND[@]}-1]} != __sentinal_arm ]]; then
        local pc kept=()
        for pc in "${PROMPT_COMMAND[@]}"; do
          [[ $pc == __sentinal_arm ]] || kept+=("$pc")
        done
        PROMPT_COMMAND=("${kept[@]}" __sentinal_arm)
      fi
    elif [[ $PROMPT_COMMAND != *";__sentinal_arm" ]]; then
      PROMPT_COMMAND="${PROMPT_COMMAND//;__sentinal_arm/};__sentinal_arm"
    fi
    if [[ -n $__sentinal_active ]]; then
      __sentinal_active=
      __sentinal_report finish --seq "$__sentinal_seq" --exit "$__sentinal_status"
    fi
    return "$__sentinal_status"
  }

  # Last in PROMPT_COMMAND: from here on, the next DEBUG trap is the user's Command.
  __sentinal_arm() {
    __sentinal_ready=1
    return "$__sentinal_status"
  }

  __sentinal_debug() {
    [[ -n $__sentinal_ready ]] || return 0
    [[ -n ${COMP_LINE-} ]] && return 0
    # Still inside PROMPT_COMMAND (a tool appended after us): not a Command.
    local pc
    for pc in "${PROMPT_COMMAND[@]}"; do
      case ";${pc//; /;};" in *";$BASH_COMMAND;"*) return 0 ;; esac
    done
    __sentinal_ready=
    local entry number text
    entry=$(HISTTIMEFORMAT= builtin history 1)
    if [[ $entry =~ ^[[:space:]]*([0-9]+)[*]?[[:space:]]+(.*)$ ]]; then
      number=${BASH_REMATCH[1]}
      text=${BASH_REMATCH[2]}
    fi
    # Not recorded in history (ignorespace, ignoredups, history off): fall back
    # to the first simple command bash is about to run.
    if [[ -z $number || $number == "$__sentinal_histnum" ]]; then
      text=$BASH_COMMAND
    fi
    __sentinal_histnum=$number
    __sentinal_start "$text"
  }

  __sentinal_bp_preexec() { __sentinal_start "$1"; }
  __sentinal_bp_precmd() { __sentinal_precmd; }

  if declare -F __bp_preexec_invoke_exec >/dev/null 2>&1; then
    # Real bash-preexec is loaded: register with it instead of the trap.
    preexec_functions+=(__sentinal_bp_preexec)
    precmd_functions=(__sentinal_bp_precmd "${precmd_functions[@]}")
    __sentinal_report register
  elif [[ -z "$(trap -p DEBUG)" ]]; then
    if [[ "$(declare -p PROMPT_COMMAND 2>/dev/null)" == "declare -a"* ]]; then
      __sentinal_pc_array=1
      PROMPT_COMMAND=(__sentinal_precmd "${PROMPT_COMMAND[@]}" __sentinal_arm)
    else
      PROMPT_COMMAND="__sentinal_precmd${PROMPT_COMMAND:+;$PROMPT_COMMAND};__sentinal_arm"
    fi
    trap '__sentinal_debug' DEBUG
    __sentinal_report register
  fi
fi
